SELECT cr.id, cr.user_id AS userId, u.name AS userName, u.employee_no AS employeeNo, u.avatar_url AS avatarUrl, d.name AS department, cr.checkin_date AS checkinDate, cr.check_in_time AS checkInTime, cr.check_out_time AS checkOutTime, cr.status FROM checkin_record cr JOIN sys_user u ON u.id = cr.user_id LEFT JOIN department d ON d.id = u.department_id WHERE 1 = 1 AND cr.checkin_date = #{date} AND cr.status = #{status}
AND (u.name LIKE CONCAT('%', #{keyword}, '%') OR u.employee_no LIKE CONCAT('%', #{keyword}, '%') OR d.name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY cr.checkin_date DESC, cr.check_in_time DESC, cr.id DESC

SELECT cr.id, cr.checkin_date AS checkinDate, cr.check_in_time AS checkInTime,
       cr.check_out_time AS checkOutTime, cr.status
FROM checkin_record cr
WHERE cr.user_id = #{userId}
AND cr.checkin_date >= #{from}
AND cr.checkin_date <= #{to}
ORDER BY cr.checkin_date DESC
